@needs_device
@pytest.mark.parametrize("mode", MODES)
@pytest.mark.parametrize("grid", [16, 64])
def test_layernorm(kt, mode, grid):
    n = grid * BLOCK
    eps = 1e-5
    x = torch.randn(n).to("kunlun")
    w = torch.randn(BLOCK).to("kunlun")
    b = torch.randn(BLOCK).to("kunlun")
    out = torch.empty(n, device="kunlun")

    _layernorm_kernel[(grid,)](x, w, b, out, BLOCK=BLOCK, EPS=eps, exec_mode=mode)
    kt.synchronize()

    ref = torch.nn.functional.layer_norm(x.cpu().view(grid, BLOCK), (BLOCK,), w.cpu(), b.cpu(), eps)
