@needs_device
@pytest.mark.parametrize("grid", [16, 64])
def test_serial_is_the_golden_reference(kt, grid):
    """T1 must agree with T0 on the same input, reduce order aside."""
    n = grid * BLOCK
    x = torch.randn(n).to("kunlun")
    serial = torch.empty(n, device="kunlun")
    distributed = torch.empty(n, device="kunlun")

    _softmax_kernel[(grid,)](x, serial, BLOCK=BLOCK, exec_mode="serial")
    _softmax_kernel[(grid,)](x, distributed, BLOCK=BLOCK, exec_mode="distributed")
    kt.synchronize()
    torch.testing.assert_close(distributed.cpu(), serial.cpu(), atol=1e-6, rtol=0)

    w = torch.randn(BLOCK).to("kunlun")
    b = torch.randn(BLOCK).to("kunlun")
    _layernorm_kernel[(grid,)](x, w, b, serial, BLOCK=BLOCK, EPS=1e-5, exec_mode="serial")
    _layernorm_kernel[(grid,)](x, w, b, distributed, BLOCK=BLOCK, EPS=1e-5, exec_mode="distributed")
    kt.synchronize()
    torch.testing.assert_close(distributed.cpu(), serial.cpu(), atol=1e-6, rtol=0)


@needs_device
@pytest.mark.parametrize("mode", MODES)
@pytest.mark.parametrize("grid", GRIDS)
def test_shift_is_arithmetic_for_signed_int(kt, mode, grid):
    """i32 `>>` must sign-extend; a logical shift turns -3 into 2147483646."""
    n = grid * BLOCK
    x = torch.randint(-1000, 1000, (n,), dtype=torch.int32)
    assert (x < 0).any()
    xk = x.to("kunlun")
    out = torch.empty(n, dtype=torch.int32, device="kunlun")

    _shr_kernel[(grid,)](xk, out, BLOCK=BLOCK, exec_mode=mode)
    kt.synchronize()

    torch.testing.assert_close(out.cpu(), x >> 1, atol=0, rtol=0)
